cd /app && cat > worktree_merge_tmp_test.go <<'EOF'
package git

import (
	"fmt"
	"testing"
)

func TestMergeTextNoTrailingNL(t *testing.T) {
	// base no trailing newline, ours modifies first line, theirs appends line
	out, conflict := mergeText("a\nb", "X\nb", "a\nb\nc")
	fmt.Printf("conflict=%v out=%q\n", conflict, out)
}
EOF
gofmt -w worktree_merge_tmp_test.go && go test . -run TestMergeTextNoTrailingNL -count=1 -v 2>&1 | tail -10 && rm -f worktree_merge_tmp_test.go
